panels.css:
main{padding:0;height:1080px;display:block}
.wrap{position:relative;height:1080px;padding:62px 56px 0;background:radial-gradient(circle at 85% 8%,rgba(245,197,24,.22),transparent 30%),radial-gradient(circle at 8% 18%,rgba(214,62,118,.28),transparent 34%),linear-gradient(180deg,#1E1219,#2A1923 70%,#46293A);color:#fff;overflow:hidden}
.spark{position:absolute;border-radius:50%;border:3px dotted rgba(245,197,24,.55)}
.s1{width:180px;height:180px;right:40px;top:20px}.s2{width:110px;height:110px;right:200px;top:110px;border-color:rgba(236,92,144,.6)}.s3{width:140px;height:140px;left:-30px;top:-20px;border-color:rgba(255,241,200,.35)}
.k{position:relative;font-size:30px;font-weight:700;color:#F5C518}
.t{position:relative;font-size:70px;font-weight:900;line-height:1.2;margin-top:12px}
.t em{font-style:normal;color:#EC5C90}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:44px}
.c{display:flex;gap:16px;align-items:flex-start;background:rgba(255,251,238,.96);color:#2A1923;border-radius:20px;padding:22px 20px;min-height:186px}
.c .n{flex:0 0 52px;height:52px;border-radius:50%;background:#D63E76;color:#fff;font-size:30px;font-weight:900;display:flex;align-items:center;justify-content:center}
.c b{display:block;font-size:33px;font-weight:900;line-height:1.25}
.c span{display:block;font-size:24px;line-height:1.5;color:#5A4651;margin-top:8px}
.foot{position:absolute;left:56px;right:56px;bottom:46px;font-size:29px;font-weight:700;text-align:center}
.foot b{color:#F5C518}
.photo{position:absolute;left:0;top:-80px;width:100%;height:calc(100% + 80px);object-fit:cover;object-position:center 40%;opacity:.9}
.shade{position:absolute;inset:0;background:linear-gradient(180deg,rgba(30,18,25,.4) 0%,rgba(30,18,25,.5) 28%,rgba(30,18,25,.6) 100%)}
.k,.t,.grid{position:relative;z-index:2}
.foot{z-index:2}

main{padding:0;height:1080px;display:block}
.wrap{position:relative;height:1080px;padding:64px 56px 0;background:radial-gradient(circle at 92% 10%,rgba(245,197,24,.22),transparent 32%),var(--cream)}
.k{font-size:30px;font-weight:700;color:#A82959}
.t{font-size:64px;font-weight:900;line-height:1.2;margin-top:10px}
.t em{font-style:normal;color:#D63E76}
.cols{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:44px}
.col{border-radius:24px;padding:26px 26px 18px;background:#fff;border:4px solid #F1DCE5}
.col.ok{border-color:#F5C518;background:#FFF8DB}
.hd{font-size:34px;font-weight:900;margin-bottom:14px}
.col.ng .hd{color:#5A4651}
ul{list-style:none}
li{font-size:31px;font-weight:700;padding:16px 0;border-bottom:2px dashed rgba(42,25,35,.12);display:flex;gap:12px;align-items:baseline}
li:last-child{border-bottom:none}
li i{font-style:normal;flex:0 0 auto;font-size:24px;font-weight:900;color:#fff;background:#D63E76;border-radius:999px;padding:2px 12px}
.col.ng li i{background:#8A7480}
.foot{position:absolute;left:56px;right:56px;bottom:46px;font-size:28px;font-weight:700;text-align:center}
.foot b{color:#D63E76}
.col{position:relative;overflow:hidden}
.col .wm{position:absolute;right:-30px;bottom:-30px;font-family:"Noto Color Emoji";font-size:300px;line-height:1;opacity:.16;pointer-events:none}
.col .hd,.col ul{position:relative;z-index:1}

main{padding:0;height:1080px;display:block}
.wrap{position:relative;height:1080px;padding:62px 56px 0;background:linear-gradient(180deg,#1E1219,#2A1923);color:#fff}
.k{font-size:30px;font-weight:700;color:#F5C518}
.t{font-size:64px;font-weight:900;line-height:1.2;margin-top:10px}
.t em{font-style:normal;color:#EC5C90}
.tl{margin-top:34px;border-left:6px solid #D63E76;padding-left:26px}
.r{position:relative;display:flex;gap:22px;align-items:baseline;padding:13px 0}
.r::before{content:'';position:absolute;left:-41px;top:26px;width:24px;height:24px;border-radius:50%;background:#2A1923;border:5px solid #D63E76}
.r b{flex:0 0 268px;font-size:34px;font-weight:900;color:#F5C518}
.r span{font-size:29px;font-weight:700;line-height:1.38}
.r.hot b{color:#EC5C90}
.car{position:absolute;left:56px;right:56px;bottom:44px;background:rgba(255,251,238,.96);color:#2A1923;border-radius:20px;padding:22px 26px;font-size:24px;line-height:1.5}
.car b{font-size:28px;color:#A82959}

main{padding:0;height:1080px;display:block}
.wrap{position:relative;height:1080px;padding:62px 56px 0;background:radial-gradient(circle at 90% 90%,rgba(214,62,118,.16),transparent 40%),var(--cream)}
.k{font-size:30px;font-weight:700;color:#A82959}
.t{font-size:74px;font-weight:900;line-height:1.15;margin-top:10px}
.t em{font-style:normal;color:#D63E76}
.b{position:relative;background:#fff;border:4px solid #F1DCE5;border-radius:26px;padding:36px 34px 32px;margin-top:40px}
.tag{position:absolute;top:-20px;left:28px;background:#2A1923;color:#F5C518;font-size:24px;font-weight:900;border-radius:999px;padding:4px 18px}
.h{font-size:44px;font-weight:900;line-height:1.25}
.h em{font-style:normal;color:#D63E76}
p{font-size:27px;line-height:1.62;margin-top:12px;color:#2A1923}
p b{color:#A82959}
ul{list-style:none;margin-top:12px}
li{font-size:31px;font-weight:700;padding:10px 0}
li b{display:inline-block;width:146px;color:#D63E76}
.b{overflow:visible}
.b .wm{position:absolute;right:24px;top:20px;font-family:"Noto Color Emoji";font-size:190px;line-height:1;opacity:.16;pointer-events:none;transform:rotate(-12deg)}
.b .wm.yt{width:250px;height:auto;top:auto;bottom:30px;right:30px;opacity:.16;transform:none}
.b .h,.b p,.b ul{position:relative;z-index:1}
